// Calculate LAST week's Sun-Sat window
// If today is Sunday, we want the week that just ended (yesterday was Saturday)
// If today is Saturday (when cron runs), we want this current week
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Sun, 6=Sat

let lastSunday;
if (dayOfWeek === 6) {
  // Saturday (cron trigger) - this week's Sunday
  lastSunday = new Date(now);
  lastSunday.setDate(now.getDate() - 6);
} else {
  // Any other day (manual trigger) - last week's Sunday
  lastSunday = new Date(now);
  lastSunday.setDate(now.getDate() - dayOfWeek - 7);
}
lastSunday.setHours(0, 0, 0, 0);

const lastSaturday = new Date(lastSunday);
lastSaturday.setDate(lastSunday.getDate() + 6);

const fromDate = lastSunday.toISOString().split('T')[0];
const toDate = lastSaturday.toISOString().split('T')[0];

return [{ json: { fromDate, toDate } }];

const results = [];

for (const inputItem of $input.all()) {
  const data = inputItem.json;
  const invoice = data.invoice || data;
  if (!invoice || !invoice.line_items || !invoice.line_items.length) continue;

  const appleItems = invoice.line_items.filter(item => {
    const category = (item.product_category || '').toLowerCase();
    return category.includes('apple retail');
  });

  if (appleItems.length === 0) continue;

  const hasGov = invoice.line_items.some(item => {
    const sku = (item.item || '').toUpperCase().trim();
    const name = (item.name || '').toUpperCase();
    return sku === 'GOV' || name === 'GOV';
  });

  const customer = invoice.customer || {};
  const customerName = (customer.business_then_name || customer.business_name || '').trim();
  const customerNameLower = customerName.toLowerCase();

  let gdvLocationId = '745667';
  if (customerNameLower.includes('getupgraded') || customerNameLower.includes('equipped')) {
    gdvLocationId = '2093771';
  } else if (customerNameLower.includes('amazon')) {
    gdvLocationId = '2060280';
  }

  for (const item of appleItems) {
    let sku = (item.item || '').trim();
    if (sku.startsWith('Z') && sku.length > 4) {
      sku = sku.substring(0, 4);
    }

    const rawDate = invoice.date || '';
    const dateFormatted = rawDate.replace(/-/g, '');

    let soldQty = Math.abs(parseInt(item.quantity) || 0);
    let returnedQty = 0;
    if (parseFloat(invoice.subtotal || '0') < 0) {
      returnedQty = soldQty;
      soldQty = 0;
    }

    results.push({
      json: {
        location: gdvLocationId,
        apple_product: sku,
        sold_qty: soldQty,
        returned_qty: returnedQty,
        invoice_number: invoice.number || '',
        invoice_date: dateFormatted,
        _rs_customer_name: customerName,
        _rs_customer_fullname: customer.fullname || '',
        _rs_customer_address: customer.address || '',
        _rs_customer_city: customer.city || '',
        _rs_customer_state: customer.state || '',
        _rs_customer_zip: customer.zip || '',
        _rs_ticket_id: invoice.ticket_id,
        _rs_invoice_id: invoice.id,
        _rs_location_id: invoice.location_id,
        _rs_has_gov: hasGov,
        _rs_contact_name: customer.fullname || '',
        _rs_item_price: item.price,
        _rs_item_name: item.name
      }
    });
  }
}

return results;

const items = $input.all().map(i => i.json);
const needsReview = items.filter(i => i._needs_review);
const autoResolved = items.filter(i => !i._needs_review);
const sources = {};
items.forEach(i => {
  sources[i._eu_source] = (sources[i._eu_source] || 0) + 1;
});
const summary = {
  report_week: $('Calculate Report Dates').first().json.fromDate + ' to ' + $('Calculate Report Dates').first().json.toDate,
  total_line_items: items.length,
  auto_resolved: autoResolved.length,
  needs_review: needsReview.length,
  eu_sources: sources,
  review_items: Object.values(needsReview.reduce((acc, i) => {
    if (!acc[i.invoice_number]) {
      acc[i.invoice_number] = {
        invoice: i.invoice_number,
        invoice_id: i._rs_invoice_id,
        ticket_id: i._rs_ticket_id,
        customer: i._rs_customer_name,
        skus: [],
        source: i._eu_source
      };
    }
    acc[i.invoice_number].skus.push(i.apple_product + ' (qty: ' + i.sold_qty + ')');
    return acc;
  }, {})),
  all_items: items.map(i => ({
    location: i.location,
    apple_product: i.apple_product,
    sold_qty: i.sold_qty,
    returned_qty: i.returned_qty,
    invoice_number: i.invoice_number,
    invoice_date: i.invoice_date,
    eu_company: i.eu_company,
    eu_name: i.eu_name,
    eu_address: i.eu_address,
    eu_city: i.eu_city,
    eu_country: i.eu_country,
    customer_type: i.customer_type
  }))
};
return [{ json: summary }];

const baseUrl = 'https://gatortec.repairshopr.com/api/v1/invoices';
const apiKey = '__PASTE_REPAIRSHOPR_API_KEY__';
const fromDate = $input.first().json.fromDate;
const toDate = $input.first().json.toDate;

let allInvoices = [];
let page = 1;
let keepGoing = true;

while (keepGoing && page <= 10) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}?api_key=${apiKey}&page=${page}&per_page=25`,
  });

  const invoices = response.invoices || [];

  if (invoices.length === 0) break;

  for (const inv of invoices) {
    const invDate = new Date(inv.date + 'T00:00:00');
    const from = new Date(fromDate + 'T00:00:00');
    const to = new Date(toDate + 'T23:59:59');

    if (invDate >= from && invDate <= to) {
      allInvoices.push(inv);
    }

    if (invDate < from) {
      keepGoing = false;
      break;
    }
  }

  page++;
}

return allInvoices.map(inv => ({ json: inv }));

// Build header row + all data rows for a single Sheets API call
const items = $('Parse EU Info + Assign Type').all();

const headers = [
  'Location', 'Apple Product #', 'Sold Qty', 'Returned Qty',
  'Invoice #', 'Invoice Date', 'EU Company', 'EU Name',
  'EU Address', 'EU City', 'Country', 'Type'
];

const rows = items.map(i => [
  i.json.location || '',
  i.json.apple_product || '',
  i.json.sold_qty || 0,
  i.json.returned_qty || 0,
  i.json.invoice_number || '',
  i.json.invoice_date || '',
  i.json.eu_company || '',
  i.json.eu_name || '',
  i.json.eu_address || '',
  i.json.eu_city || '',
  i.json.eu_country || '',
  i.json.customer_type || 'EN'
]);

// Sheet tab name matches the one Create sheet just made
const sheetName = $('Create sheet').first().json.title;

return [{ json: { sheetName, rowCount: rows.length + 1, allValues: [headers, ...rows] } }];

const s = $('Compile Report Summary').first().json;
const sheetId = $('Create sheet').first().json.sheetId;

const reviewText = s.needs_review > 0
  ? '*Needs Review:*\n' + s.review_items.map(i =>
      `• <https://gatortec.repairshopr.com/invoices/${i.invoice_id}|Invoice ${i.invoice}> | ${i.customer} | <https://gatortec.repairshopr.com/tickets/${i.ticket_id}|Ticket>`
    ).join('\n')
  : 'All items auto-resolved! 🎉';

const blocks = [
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `📊 *GDV Weekly Review — ${s.report_week}*\n*${s.total_line_items}* line items this week\n✅ *${s.auto_resolved}* auto-resolved\n⚠️ *${s.needs_review}* need your review\n\n${reviewText}\n\n📝 <https://docs.google.com/spreadsheets/d/1EolT-rt_mDE3f7Ky4JUpf5BX9czVZkCg7mRfQmbVBBo/edit#gid=${sheetId}|Edit in Google Sheets>`
    }
  },
  {
    type: 'actions',
    elements: [{
      type: 'button',
      text: { type: 'plain_text', text: '✅ Review Complete — Generate Reports', emoji: true },
      style: 'primary',
      action_id: 'gdv_generate'
    }]
  }
];

return [{ json: { blocks, fallback: `GDV Weekly Review — ${s.report_week}` } }];
